<script lang="ts">
 import type {CheckpointState} from '../core/editor-checkpoint';
 let {phase,changedAt}:{phase:CheckpointState;changedAt:number}=$props();let slow=$state(false),open=$state(false);
 $effect(()=>{changedAt;slow=false;if(phase==='pending'){const timer=setTimeout(()=>slow=true,2200);return()=>clearTimeout(timer);}});
 const label=$derived(phase==='error'?'\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c \u0447\u0435\u0440\u043d\u043e\u0432\u0438\u043a':slow?'\u0421\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u043c \u0447\u0435\u0440\u043d\u043e\u0432\u0438\u043a\u2026':phase==='pending'?'\u0410\u0432\u0442\u043e\u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u0435 \u0447\u0435\u0440\u043d\u043e\u0432\u0438\u043a\u0430 \u0432\u043a\u043b\u044e\u0447\u0435\u043d\u043e':'\u0427\u0435\u0440\u043d\u043e\u0432\u0438\u043a \u0441\u043e\u0445\u0440\u0430\u043d\u0451\u043d \u043d\u0430 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0435');
</script>
<div class="draft-indicator" class:error={phase==='error'}><button type="button" title={label} aria-label={label} aria-expanded={open} onclick={()=>open=!open}><svg viewBox="0 0 24 24" aria-hidden="true">{#if phase==='error'}<circle cx="12" cy="12" r="8"/><path d="M12 7v6m0 3h.01"/>{:else if slow}<circle cx="12" cy="12" r="8"/><path d="M12 7v5l3 2"/>{:else}<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6ZM8 12l3 3 5-6"/>{/if}</svg></button>{#if open}<span>{label}</span>{/if}</div>
<style>.draft-indicator{position:relative;display:flex;justify-content:flex-end;align-items:center;min-height:24px;color:var(--theme-muted);flex:none}.draft-indicator button{display:grid;place-items:center;padding:3px;min-height:24px;min-width:32px;background:transparent;border:0;color:inherit}.draft-indicator svg{width:15px;height:15px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}.draft-indicator.error{color:var(--theme-danger)}span{font-size:11px;position:absolute;right:34px;bottom:4px;padding:6px 10px;background:var(--theme-surface);border:1px solid var(--theme-border);border-radius:10px;max-width:calc(100vw - 90px);white-space:nowrap}</style>
